-- bm constraints from live project. Ordered: PK/UNIQUE first, then CHECK, then FOREIGN KEY (FKs need the unique keys to exist).
alter table bm.activity_logs add constraint activity_logs_pkey PRIMARY KEY (id);
alter table bm.bottom_pw_fails add constraint bottom_pw_fails_pkey PRIMARY KEY (id);
alter table bm.bottom_requests add constraint bottom_requests_pkey PRIMARY KEY (truck_id);
alter table bm.companies add constraint companies_pkey PRIMARY KEY (name, lot);
alter table bm.composite_batches add constraint composite_batches_pkey PRIMARY KEY (composite_ref_id);
alter table bm.composite_batches add constraint bm_composite_group_uq UNIQUE (date, daily_group_code);
alter table bm.composite_batches add constraint composite_batches_composite_barcode_id_key UNIQUE (composite_barcode_id);
alter table bm.counters add constraint counters_pkey PRIMARY KEY (name, day);
alter table bm.known_ips add constraint known_ips_pkey PRIMARY KEY (ip);
alter table bm.lab1_results add constraint lab1_results_pkey PRIMARY KEY (sample1_barcode_id);
alter table bm.log_acks add constraint log_acks_pkey PRIMARY KEY (log_id);
alter table bm.mixing_groups add constraint mixing_groups_pkey PRIMARY KEY (entry_date, company_name, lot);
alter table bm.mixing_groups add constraint bm_mixing_groups_code_uq UNIQUE (entry_date, group_code);
alter table bm.mixing_scans add constraint mixing_scans_pkey PRIMARY KEY (sample1_barcode_id);
alter table bm.profiles add constraint profiles_pkey PRIMARY KEY (id);
alter table bm.profiles add constraint profiles_username_key UNIQUE (username);
alter table bm.qr_history add constraint qr_history_pkey PRIMARY KEY (id);
alter table bm.reader_templates add constraint reader_templates_pkey PRIMARY KEY (version);
alter table bm.reader_training add constraint reader_training_pkey PRIMARY KEY (id);
alter table bm.recovery_fails add constraint recovery_fails_pkey PRIMARY KEY (id);
alter table bm.settings add constraint settings_pkey PRIMARY KEY (key);
alter table bm.trucks add constraint trucks_pkey PRIMARY KEY (truck_id);
alter table bm.trucks add constraint trucks_sample1_barcode_id_key UNIQUE (sample1_barcode_id);
alter table bm.trusted_devices add constraint trusted_devices_pkey PRIMARY KEY (id);
alter table bm.verified_sessions add constraint verified_sessions_pkey PRIMARY KEY (session_id);
alter table bm.voided_composites add constraint voided_composites_pkey PRIMARY KEY (id);
alter table bm.bottom_requests add constraint bottom_requests_status_check CHECK ((status = ANY (ARRAY['REQUESTED'::text, 'GENERATED'::text])));
alter table bm.companies add constraint bm_companies_lot_ck CHECK ((lot = ANY (ARRAY['LOT2/3'::text, 'LOT2'::text, 'LOT3'::text, 'LOT4'::text, 'LOT4A'::text])));
alter table bm.profiles add constraint bm_profiles_role_ck CHECK ((role = ANY (ARRAY['superadmin'::text, 'admin'::text, 'entry'::text, 'weighment'::text, 'unloading'::text, 'lab1'::text, 'lab1m'::text, 'lab1f'::text, 'lab2'::text])));
alter table bm.reader_training add constraint reader_training_kind_check CHECK ((kind = ANY (ARRAY['moisture'::text, 'fineness_initial'::text, 'fineness_final'::text])));
alter table bm.reader_training add constraint reader_training_status_check CHECK ((status = ANY (ARRAY['PENDING'::text, 'USED'::text, 'REJECTED'::text])));
alter table bm.trucks add constraint bm_trucks_cancel_ck CHECK (((cancel_status IS NULL) OR (cancel_status = ANY (ARRAY['CANCELLED'::text, 'VOIDED'::text]))));
alter table bm.trucks add constraint bm_trucks_override_ck CHECK (((acceptance_override IS NULL) OR (acceptance_override = ANY (ARRAY['ACCEPTED'::text, 'REJECTED'::text]))));
alter table bm.trusted_devices add constraint trusted_devices_status_check CHECK ((status = ANY (ARRAY['PENDING'::text, 'TRUSTED'::text, 'REVOKED'::text])));
alter table bm.bottom_requests add constraint bottom_requests_truck_id_fkey FOREIGN KEY (truck_id) REFERENCES bm.trucks(truck_id);
alter table bm.lab1_results add constraint lab1_results_sample1_barcode_id_fkey FOREIGN KEY (sample1_barcode_id) REFERENCES bm.trucks(sample1_barcode_id) ON UPDATE CASCADE;
alter table bm.mixing_scans add constraint mixing_scans_sample1_barcode_id_fkey FOREIGN KEY (sample1_barcode_id) REFERENCES bm.trucks(sample1_barcode_id) ON UPDATE CASCADE;
alter table bm.profiles add constraint profiles_id_fkey FOREIGN KEY (id) REFERENCES auth.users(id) ON DELETE CASCADE;
